26	export class InvalidEvaluationMeasurementsError extends Error {
27	  constructor(message: string) {
28	    super(`Invalid evaluation measurements: ${message}`);
29	    this.name = "InvalidEvaluationMeasurementsError";
30	  }
31	}
32	
33	function requireCount(value: number, label: string): void {
34	  if (!Number.isSafeInteger(value) || value < 0) {
35	    throw new InvalidEvaluationMeasurementsError(`${label} must be a non-negative safe integer`);
36	  }
37	}
38	
39	function countContextTokens(
40	  items: readonly PipelineRunResult["inventory"]["items"][number][],
41	  estimator: Pick<PromptTokenEstimator, "countContextItem">,
42	): number {
43	  return items.reduce((total, item) => {
44	    const itemTokens = estimator.countContextItem(item);
45	    requireCount(itemTokens, `token estimate for item ${item.id}`);
